/* ════════════════════════════════════════════════════════════════
   THEME TOGGLE — with View Transitions API for circular reveal
   ──────────────────────────────────────────────────────────────
   Modern browsers (Chrome/Edge): the new theme expands as a circle
   from the click point. Older browsers: clean CSS transitions
   handle it via the `transition: 0.5s` rules on every element.
══════════════════════════════════════════════════════════════════ */
const themeBtn = document.getElementById('themeBtn');
const html = document.documentElement;

const saved = localStorage.getItem('theme');
if (saved) {
  html.setAttribute('data-theme', saved);
  themeBtn.textContent = saved === 'dark' ? '🌙' : '☀️';
}

function switchTheme() {
  const current = html.getAttribute('data-theme');
  // If in naruto mode, exit to dark
  if (current === 'naruto') {
    html.setAttribute('data-theme', 'dark');
    localStorage.setItem('theme', 'dark');
    themeBtn.textContent = '🌙';
    return;
  }
  // Normal toggle between dark and light
  const next = current === 'dark' ? 'light' : 'dark';
  html.setAttribute('data-theme', next);
  localStorage.setItem('theme', next);
  themeBtn.textContent = next === 'dark' ? '🌙' : '☀️';
}

themeBtn.addEventListener('click', (e) => {
  // Where did the user click? Use that point as the reveal origin.
  const rect = themeBtn.getBoundingClientRect();
  const x = rect.left + rect.width / 2;
  const y = rect.top + rect.height / 2;

  // Convert to percentages so the reveal animation uses the right origin
  html.style.setProperty('--tx', (x / window.innerWidth * 100) + '%');
  html.style.setProperty('--ty', (y / window.innerHeight * 100) + '%');

  // If browser doesn't support View Transitions, fall back to plain CSS
  if (!document.startViewTransition) {
    switchTheme();
    return;
  }

  // Otherwise, kick off the circular reveal animation
  document.startViewTransition(() => switchTheme());
});

/* ════════════════════════════════════════════════════════════════
   SCROLL-DRIVEN AMBIENT ORBS
══════════════════════════════════════════════════════════════════ */
let orbTicking = false;
window.addEventListener('scroll', () => {
  if (orbTicking) return;
  orbTicking = true;
  requestAnimationFrame(() => {
    const y = window.pageYOffset;
    const ox = Math.sin(y * 0.005) * 60 + Math.cos(y * 0.003) * 40;
    const oy = Math.cos(y * 0.004) * 50 + Math.sin(y * 0.007) * 30;
    document.body.style.setProperty('--orb-x', ox + 'px');
    document.body.style.setProperty('--orb-y', oy + 'px');
    orbTicking = false;
  });
}, { passive: true });

/* ════════════════════════════════════════════════════════════════
   NARUTO EASTER EGG — Triple-click the hero name
══════════════════════════════════════════════════════════════════ */
let substitutionTriggered = false;
const heroNameWrap = document.getElementById('hero-name-wrap');
const narutoH1Img  = document.querySelector('.hero-naruto-h1');
let nameClickCount = 0;
let nameClickTimer = null;
let preNarutoTheme = null;

function handleNameClick() {
  nameClickCount++;
  clearTimeout(nameClickTimer);
  if (nameClickCount === 3) {
    const isNaruto = html.getAttribute('data-theme') === 'naruto';
    if (isNaruto) {
      html.setAttribute('data-theme', preNarutoTheme || 'dark');
      localStorage.setItem('theme', preNarutoTheme || 'dark');
      preNarutoTheme = null;
      substitutionTriggered = false;
      // Clean up: remove any wood logs, restore portrait
      document.querySelectorAll('.wood-log-fixed').forEach(el => el.remove());
      if (portraitImg) portraitImg.style.opacity = '1';
    } else {
      preNarutoTheme = html.getAttribute('data-theme');
      triggerBelieveIt();
    }
    nameClickCount = 0;
  } else {
    nameClickTimer = setTimeout(() => { nameClickCount = 0; }, 1500);
  }
}

heroNameWrap.addEventListener('click', handleNameClick);
if (narutoH1Img) narutoH1Img.addEventListener('click', handleNameClick);

/* ════════════════════════════════════════════════════════════════
   SUBSTITUTION JUTSU — scroll-triggered, in-place
   Uses absolute positioning relative to document so the log
   stays exactly where the portrait was and scrolls naturally.
══════════════════════════════════════════════════════════════════ */
const portraitImg = document.getElementById('headshot-image');

window.addEventListener('scroll', () => {
  if (substitutionTriggered || !portraitImg) return;
    const rect = portraitImg.getBoundingClientRect();
  // Fire when portrait has scrolled past viewport
  if (rect.bottom <= 100) {
    substitutionTriggered = true;
    triggerSubstitution(rect);
  }
}, { passive: true });

function triggerSubstitution(rect) {
  // Document-level coordinates (survives scroll)
  const scrollY  = window.scrollY || window.pageYOffset;
  const scrollX  = window.scrollX || window.pageXOffset;
  const docTop   = rect.top  + scrollY;
  const docLeft  = rect.left + scrollX;
  const w = rect.width;
  const h = rect.height;
  const cx = docLeft + w / 2;
  const cy = docTop  + h / 2;

  // 1. Fade portrait
  portraitImg.style.transition = 'opacity 0.3s ease';
  portraitImg.style.opacity = '0';

  // 2. Poof particles at viewport position
  spawnPoof(rect.left + w/2, rect.top + h/2, 18);

  // 3. Build bamboo log + smoke at document position
  setTimeout(() => {
    const logW = Math.min(w * 1.45, 285);

    const wrap = document.createElement('div');
    wrap.className = 'wood-log-fixed';
    wrap.style.cssText = `left:${cx - logW/2}px; top:${docTop + h*0.15}px; width:${logW}px;`;

    // Actual anime log image — no bg PNG
    const logImg = document.createElement('img');
    logImg.src = 'data:image/png;base64,';
    logImg.style.cssText = 'width:100%;height:auto;display:block;transform:scaleX(-1) rotate(-8deg);filter:drop-shadow(0 12px 32px rgba(0,0,0,0.4));transform-origin:center center;';
    wrap.appendChild(logImg);

    // Puffy smoke clouds
    const clouds = [
      { size: 90, sx: -65, sy: -30, delay: 0.0,  dur: 2.2 },
      { size: 80, sx:  60, sy: -40, delay: 0.08, dur: 2.0 },
      { size: 100,sx: -15, sy: -70, delay: 0.04, dur: 2.4 },
      { size: 70, sx:  40, sy:  25, delay: 0.15, dur: 1.9 },
      { size: 60, sx: -50, sy:  35, delay: 0.2,  dur: 1.8 },
      { size: 85, sx:  15, sy: -90, delay: 0.06, dur: 2.1 },
      { size: 55, sx:  75, sy:  15, delay: 0.25, dur: 1.7 },
      { size: 65, sx: -80, sy: -55, delay: 0.12, dur: 2.0 },
    ];
    clouds.forEach(c => {
      const s = document.createElement('div');
      s.className = 'smoke-cloud';
      s.style.cssText = `
        width:${c.size}px; height:${c.size * 0.75}px;
        left:${logW/2 - c.size/2}px; top:${logW * 0.3}px;
        --sx:${c.sx}px; --sy:${c.sy}px;
        --dur:${c.dur}s; --delay:${c.delay}s;`;
      wrap.appendChild(s);
    });

    document.body.appendChild(wrap);

    // Second poof burst when log appears
    spawnPoof(rect.left + w/2, rect.top + h*0.4, 10);
  }, 280);
}

function spawnPoof(cx, cy, count = 14) {
  const colors = ['#fff','#f0f0f0','#e4e4e4','#d8d8d8','#ececec'];
  for (let i = 0; i < count; i++) {
    const p = document.createElement('div');
    p.className = 'poof-particle';
    const size  = Math.random() * 20 + 8;
    const angle = Math.random() * Math.PI * 2;
    const dist  = Math.random() * 110 + 40;
    const dur   = (Math.random() * 0.4 + 0.5).toFixed(2);
    p.style.cssText = `
      width:${size}px; height:${size}px;
      background:${colors[Math.floor(Math.random()*colors.length)]};
      left:${cx}px; top:${cy}px;
      --tx:${Math.cos(angle)*dist}px;
      --ty:${Math.sin(angle)*dist - 55}px;
      animation:poofBurst ${dur}s ease-out forwards;`;
    document.body.appendChild(p);
    setTimeout(() => p.remove(), +dur * 1000 + 50);
  }
}

function triggerBelieveIt() {
  const overlay = document.createElement('div');
  overlay.id = 'believe-overlay';
  // BELIEVE IT!! bounces in first, then Juan Hume pops in below it
  overlay.innerHTML = `<img class="believe-img" src="data:image/png;base64," alt="BELIEVE IT!!" />`;
  document.body.appendChild(overlay);

  // Hold for ~3s so both lines are visible, then switch theme + fade out
  setTimeout(() => {
    html.setAttribute('data-theme', 'naruto');
    overlay.classList.add('exit');
    setTimeout(() => overlay.remove(), 600);
  }, 3000);
}

/* ════════════════════════════════════════════════════════════════
   ANIMATED STAT COUNTERS
══════════════════════════════════════════════════════════════════ */
function animateStat(el) {
  const target = parseInt(el.dataset.target, 10);
  const suffix = el.dataset.suffix || '';
  const useText = el.dataset.text;
  if (target === 0 && useText !== undefined) {
    el.textContent = useText + suffix;
    return;
  }
  const duration = 1200;
  const start = performance.now();
  function step(now) {
    const progress = Math.min((now - start) / duration, 1);
    const eased = 1 - Math.pow(1 - progress, 3);
    el.textContent = Math.round(eased * target) + suffix;
    if (progress < 1) requestAnimationFrame(step);
    else el.textContent = target + suffix;
  }
  requestAnimationFrame(step);
}

const observer = new IntersectionObserver((entries) => {
  entries.forEach(entry => {
    if (entry.isIntersecting) {
      animateStat(entry.target);
      observer.unobserve(entry.target);
    }
  });
}, { threshold: 0.5 });
document.querySelectorAll('[data-target]').forEach(el => observer.observe(el));

/* ════════════════════════════════════════════════════════════════
   PROGRESSIVE DISCLOSURE
══════════════════════════════════════════════════════════════════ */
document.querySelectorAll('.hard-part-toggle').forEach(btn => {
  btn.addEventListener('click', () => {
    const targetId = btn.getAttribute('aria-controls');
    const body = document.getElementById(targetId);
    const arrow = btn.querySelector('.toggle-arrow');
    const isOpen = body.classList.contains('expanded');
    body.classList.toggle('expanded', !isOpen);
    arrow.classList.toggle('open', !isOpen);
    btn.setAttribute('aria-expanded', String(!isOpen));
  });
});

/* ════════════════════════════════════════════════════════════════
   OROCHIMARU SNAKE — enhanced
   • Directional head with eyes
   • Glowing pulsing chakra food
   • Gradient body (bright → dark toward tail)
   • Canvas border pulses with score, red-shifts near danger
   • Screen shake on death
   • Flash on eat
   • Mid-game Orochimaru taunts at milestones
   • Countdown before start
   • Cursed seal power-up (rare gold orb = brief invincibility)
   • Poison tiles appear after score 15
══════════════════════════════════════════════════════════════════ */
const canvas = document.getElementById('snake-canvas');
const ctx = canvas.getContext('2d');
const scoreEl = document.getElementById('score-display');
const hiEl    = document.getElementById('hi-display');
const startBtn  = document.getElementById('snake-start-btn');
const outcomeBox = document.getElementById('game-outcome');
const outcomeMsg = document.getElementById('outcome-message');
const outcomeBtn = document.getElementById('outcome-email');

const WIN_SCORE = 30;
const MY_EMAIL  = 'dajuan.hume@gmail.com';
const COLS = 20, ROWS = 20;
const CELL = canvas.width / COLS;

const COL_BG    = '#05030a';
const COL_GRID  = '#24123a';
const COL_HEAD  = '#f5e6c8';
const COL_BODY  = '#7c3aed';
const COL_BODY2 = '#a855f7';
const COL_FOOD  = '#7fff7f';

let snake, direction, nextDir, food, score, hiScore, gameLoop, alive;
let cursedSeal = null;      // gold power-up position, null if not spawned
let sealActive = false;     // invincibility on
let sealTimer  = null;
let poisonTiles = [];       // [{x,y}] danger tiles
let shakeFrames = 0;        // countdown for death shake
let flashFrames = 0;        // countdown for eat flash
let tauntText   = '';       // current mid-game taunt
let tauntAlpha  = 0;        // fade value 0-1
let foodPulse   = 0;        // animation clock
let idleAnim    = 0;        // idle screen animation clock
let idleRaf     = null;
let countdownActive = false;

hiScore = parseInt(localStorage.getItem('snakeHi') || '0');
hiEl.textContent = hiScore;

/* ── Orochimaru quotes ─────────────────────────────────────────── */
const LOSE_QUOTES = [
  "You are not fit to be my vessel.",
  "Kukukuku... how disappointing.",
  "Pathetic. Such wasted potential.",
  "You're not even worth using.",
  "Foolish child. Did you truly believe you could survive?",
  "Such a waste. Now — hand over the job offer.",
  "Worthless. I expected more."
];
const TAUNT_QUOTES = {
  5:  "Kukuku... not bad for a mortal.",
  10: "You're starting to interest me.",
  15: "I'll give you a chance to impress me further.",
  20: "Perhaps you are worthy after all...",
  25: "Only five more. Don't disappoint me."
};
let shownTaunts = new Set();

/* ── Canvas border glow (updates outside draw loop) ───────────── */
function updateBorderGlow() {
  if (!alive) return;
  const danger = score >= WIN_SCORE - 5;
  const intensity = Math.min(score / WIN_SCORE, 1);
  const r = danger ? Math.round(180 + intensity * 75) : Math.round(80 + intensity * 40);
  const g = danger ? 20 : Math.round(20 + intensity * 20);
  const b = danger ? 20 : Math.round(200 + intensity * 55);
  const blur = 8 + intensity * 16;
  canvas.style.boxShadow = `0 0 ${blur}px rgba(${r},${g},${b},0.7), inset 0 0 ${blur/2}px rgba(${r},${g},${b},0.2)`;
}

/* ── Grid ──────────────────────────────────────────────────────── */
function drawGrid() {
  ctx.strokeStyle = COL_GRID; ctx.lineWidth = 0.5;
  for (let x = 0; x <= COLS; x++) {
    ctx.beginPath(); ctx.moveTo(x*CELL,0); ctx.lineTo(x*CELL,canvas.height); ctx.stroke();
  }
  for (let y = 0; y <= ROWS; y++) {
    ctx.beginPath(); ctx.moveTo(0,y*CELL); ctx.lineTo(canvas.width,y*CELL); ctx.stroke();
  }
}

/* ── Food spawn ────────────────────────────────────────────────── */
function spawnFood() {
  let pos;
  do { pos = {x:Math.floor(Math.random()*COLS), y:Math.floor(Math.random()*ROWS)}; }
  while (snake.some(s=>s.x===pos.x&&s.y===pos.y) || poisonTiles.some(p=>p.x===pos.x&&p.y===pos.y));
  food = pos;

  // 18% chance to also spawn cursed seal if none active
  if (!cursedSeal && !sealActive && Math.random() < 0.18) {
    let sp;
    do { sp = {x:Math.floor(Math.random()*COLS), y:Math.floor(Math.random()*ROWS)}; }
    while (snake.some(s=>s.x===sp.x&&s.y===sp.y) || (sp.x===food.x&&sp.y===food.y) || poisonTiles.some(p=>p.x===sp.x&&p.y===sp.y));
    cursedSeal = sp;
  }
}

/* ── Poison tiles ──────────────────────────────────────────────── */
function addPoisonTile() {
  let pt;
  let attempts = 0;
  do {
    pt = {x:Math.floor(Math.random()*COLS), y:Math.floor(Math.random()*ROWS)};
    attempts++;
  } while (attempts < 40 && (
    snake.some(s=>s.x===pt.x&&s.y===pt.y) ||
    (food && pt.x===food.x&&pt.y===food.y) ||
    (cursedSeal && pt.x===cursedSeal.x&&pt.y===cursedSeal.y) ||
    poisonTiles.some(p=>p.x===pt.x&&p.y===pt.y)
  ));
  if (attempts < 40) poisonTiles.push(pt);
}

/* ── Directional head ──────────────────────────────────────────── */
function drawHead(x, y, dir) {
  const px = x*CELL+1, py = y*CELL+1, s = CELL-2;
  ctx.save();
  ctx.translate(px + s/2, py + s/2);

  // Glow when seal active
  if (sealActive) {
    ctx.shadowBlur = 12;
    ctx.shadowColor = '#fbbf24';
  }

  // Rounded head body
  ctx.fillStyle = COL_HEAD;
  ctx.beginPath();
  ctx.roundRect(-s/2, -s/2, s, s, 5);
  ctx.fill();

  // Snout point in movement direction
  ctx.fillStyle = '#e8d5b0';
  const snoutSize = s * 0.28;
  const snoutX = dir.x * s * 0.3;
  const snoutY = dir.y * s * 0.3;
  ctx.beginPath();
  ctx.ellipse(snoutX, snoutY, snoutSize, snoutSize * 0.75, Math.atan2(dir.y, dir.x), 0, Math.PI*2);
  ctx.fill();

  // Eyes — perpendicular to movement direction
  const eyeOffset = s * 0.22;
  const eyeForward = s * 0.12;
  const perpX = -dir.y, perpY = dir.x;
  const eyeR = s * 0.1;
  [[1,-1],[-1,1]].forEach(([flip]) => {
    const ex = dir.x*eyeForward + perpX*eyeOffset*flip;
    const ey = dir.y*eyeForward + perpY*eyeOffset*flip;
    // White sclera
    ctx.fillStyle = '#fff';
    ctx.beginPath(); ctx.arc(ex, ey, eyeR, 0, Math.PI*2); ctx.fill();
    // Slit pupil — gold when seal active, red otherwise
    ctx.fillStyle = sealActive ? '#fbbf24' : '#cc0000';
    ctx.beginPath(); ctx.ellipse(ex, ey, eyeR*0.35, eyeR*0.7, Math.atan2(dir.y,dir.x), 0, Math.PI*2); ctx.fill();
  });

  ctx.restore();
}

/* ── Body segment ──────────────────────────────────────────────── */
function drawBody(x, y, idx, total) {
  const t = idx / Math.max(total - 1, 1);
  // Interpolate purple → near-black toward tail
  const r = Math.round((1-t)*124 + t*20);
  const g = Math.round((1-t)*58  + t*5);
  const b = Math.round((1-t)*237 + t*40);
  const alpha = 1 - t * 0.35;
  ctx.fillStyle = `rgba(${r},${g},${b},${alpha})`;
  if (sealActive) { ctx.shadowBlur = 6; ctx.shadowColor = '#fbbf24'; }
  ctx.beginPath();
  ctx.roundRect(x*CELL+2, y*CELL+2, CELL-4, CELL-4, idx%2===0 ? 4 : 3);
  ctx.fill();
  ctx.shadowBlur = 0;
}

/* ── Glowing food orb ──────────────────────────────────────────── */
function drawFood(x, y) {
  const cx = x*CELL + CELL/2, cy = y*CELL + CELL/2;
  const r  = CELL/2 - 2;
  const pulse = 0.7 + Math.sin(foodPulse * 0.12) * 0.3;

  ctx.save();
  ctx.shadowBlur  = 14 * pulse;
  ctx.shadowColor = '#7fff7f';
  const grad = ctx.createRadialGradient(cx-r*0.2, cy-r*0.2, r*0.1, cx, cy, r*pulse);
  grad.addColorStop(0, '#ccffcc');
  grad.addColorStop(0.5, '#7fff7f');
  grad.addColorStop(1, '#00aa44');
  ctx.fillStyle = grad;
  ctx.beginPath(); ctx.arc(cx, cy, r*pulse, 0, Math.PI*2); ctx.fill();
  ctx.restore();
}

/* ── Cursed seal orb ───────────────────────────────────────────── */
function drawSeal(x, y) {
  if (!cursedSeal) return;
  const cx = x*CELL + CELL/2, cy = y*CELL + CELL/2;
  const r  = CELL/2 - 2;
  const pulse = 0.75 + Math.sin(foodPulse * 0.18 + 1.5) * 0.25;
  ctx.save();
  ctx.shadowBlur  = 18 * pulse;
  ctx.shadowColor = '#fbbf24';
  const grad = ctx.createRadialGradient(cx, cy, r*0.1, cx, cy, r*pulse);
  grad.addColorStop(0, '#fffbeb');
  grad.addColorStop(0.4, '#fbbf24');
  grad.addColorStop(1, '#b45309');
  ctx.fillStyle = grad;
  ctx.beginPath(); ctx.arc(cx, cy, r*pulse, 0, Math.PI*2); ctx.fill();
  // 咒 seal symbol
  ctx.fillStyle = 'rgba(0,0,0,0.6)';
  ctx.font = `bold ${CELL*0.55}px serif`;
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText('咒', cx, cy);
  ctx.restore();
}

/* ── Poison tile ───────────────────────────────────────────────── */
function drawPoisonTile(x, y) {
  const px = x*CELL+1, py = y*CELL+1, s = CELL-2;
  ctx.save();
  ctx.shadowBlur = 6; ctx.shadowColor = '#7f1d1d';
  ctx.fillStyle = 'rgba(127,29,29,0.75)';
  ctx.beginPath(); ctx.roundRect(px, py, s, s, 3); ctx.fill();
  ctx.fillStyle = '#f87171';
  ctx.font = `${CELL*0.5}px serif`;
  ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
  ctx.fillText('☠', px+s/2, py+s/2);
  ctx.restore();
}

/* ── Taunt overlay ─────────────────────────────────────────────── */
function drawTaunt() {
  if (tauntAlpha <= 0) return;
  ctx.save();
  ctx.globalAlpha = tauntAlpha;
  ctx.fillStyle = '#d8b4fe';
  ctx.font = `italic ${CELL*0.72}px 'Playfair Display',serif`;
  ctx.textAlign = 'center';
  ctx.shadowBlur = 8; ctx.shadowColor = '#7c3aed';
  ctx.fillText(tauntText, canvas.width/2, CELL*1.6);
  ctx.restore();
  tauntAlpha = Math.max(0, tauntAlpha - 0.008);
}

/* ── Main draw ─────────────────────────────────────────────────── */
function draw() {
  ctx.save();

  // Screen shake
  if (shakeFrames > 0) {
    ctx.translate((Math.random()-0.5)*6, (Math.random()-0.5)*6);
    shakeFrames--;
  }

  // Eat flash overlay
  if (flashFrames > 0) {
    ctx.fillStyle = COL_BG;
    ctx.fillRect(0,0,canvas.width,canvas.height);
    ctx.fillStyle = `rgba(127,255,127,${flashFrames/8 * 0.35})`;
    ctx.fillRect(0,0,canvas.width,canvas.height);
    flashFrames--;
  } else {
    ctx.fillStyle = COL_BG;
    ctx.fillRect(0,0,canvas.width,canvas.height);
  }

  drawGrid();
  poisonTiles.forEach(p => drawPoisonTile(p.x, p.y));
  drawFood(food.x, food.y);
  if (cursedSeal) drawSeal(cursedSeal.x, cursedSeal.y);

  // Body (back to front, skip head)
  ctx.shadowBlur = 0;
  for (let i = snake.length-1; i >= 1; i--) drawBody(snake[i].x, snake[i].y, i, snake.length);

  // Directional head
  if (snake.length > 0) drawHead(snake[0].x, snake[0].y, direction);

  drawTaunt();
  foodPulse++;
  updateBorderGlow();

  ctx.restore();
}

/* ── Tick ──────────────────────────────────────────────────────── */
function tick() {
  direction = nextDir;
  const head = snake[0];
  let next = {x: head.x + direction.x, y: head.y + direction.y};

  // Wall collision — wrap if seal active, die otherwise
  if (next.x < 0 || next.x >= COLS || next.y < 0 || next.y >= ROWS) {
    if (sealActive) {
      next = {x: (next.x + COLS) % COLS, y: (next.y + ROWS) % ROWS};
    } else {
      return endGame();
    }
  }

  // Check if heading to seal FIRST — skip all collision checks if so
  const eatingSeal = !!(cursedSeal && next.x === cursedSeal.x && next.y === cursedSeal.y);

  if (!eatingSeal) {
    // Self collision — pass through if seal active
    if (!sealActive && snake.slice(0,-1).some(s => s.x===next.x && s.y===next.y)) return endGame();
    // Poison — seal blocks it
    if (!sealActive && poisonTiles.some(p => p.x===next.x && p.y===next.y)) return endGame();
  }

  snake.unshift(next);

  // Eat regular food
  if (next.x === food.x && next.y === food.y) {
    score++;
    scoreEl.textContent = score;
    flashFrames = 8;
    if (score > hiScore) { hiScore = score; hiEl.textContent = hiScore; localStorage.setItem('snakeHi', hiScore); }
    clearInterval(gameLoop);
    gameLoop = setInterval(tick, Math.max(52, 120 - score * 2));
    spawnFood();
    if (score >= 15 && score % 3 === 0) addPoisonTile();
    if (TAUNT_QUOTES[score] && !shownTaunts.has(score)) {
      tauntText = TAUNT_QUOTES[score]; tauntAlpha = 1; shownTaunts.add(score);
    }
  }
  // Eat cursed seal
  else if (eatingSeal) {
    cursedSeal = null;
    sealActive = true;
    flashFrames = 14;
    canvas.style.outline = '2px solid #fbbf24';
    clearTimeout(sealTimer);
    sealTimer = setTimeout(() => {
      sealActive = false;
      canvas.style.outline = '';
    }, 4000);
    snake.pop(); // don't grow when eating seal
  }
  else { snake.pop(); }

  draw();
}

/* ── Countdown then start ──────────────────────────────────────── */
function runCountdown(cb) {
  countdownActive = true;
  let count = 3;
  function frame() {
    ctx.fillStyle = COL_BG; ctx.fillRect(0,0,canvas.width,canvas.height);
    drawGrid();
    ctx.fillStyle = '#d8b4fe';
    ctx.font = `bold ${CELL*2.8}px 'Playfair Display',serif`;
    ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
    ctx.shadowBlur = 20; ctx.shadowColor = '#7c3aed';
    ctx.fillText(count, canvas.width/2, canvas.height/2);
    ctx.shadowBlur = 0;
    ctx.fillStyle = '#b794f4';
    ctx.font = `${CELL*0.5}px 'DM Sans',sans-serif`;
    ctx.textBaseline = 'alphabetic';
    ctx.fillText('Get ready...', canvas.width/2, canvas.height/2 + CELL*2);
    count--;
    if (count >= 0) setTimeout(frame, 800);
    else { countdownActive = false; cb(); }
  }
  frame();
}

/* ── Death ─────────────────────────────────────────────────────── */
function endGame() {
  alive = false;
  clearInterval(gameLoop);
  clearTimeout(sealTimer);
  sealActive = false;
  canvas.style.outline = '';
  canvas.style.boxShadow = '0 0 20px rgba(200,20,20,0.8)';
  shakeFrames = 20;

  // Shake then show result
  let shakeRaf;
  function shakeEnd() {
    if (shakeFrames > 0) {
      ctx.save();
      ctx.fillStyle = COL_BG; ctx.fillRect(0,0,canvas.width,canvas.height);
      ctx.translate((Math.random()-0.5)*8, (Math.random()-0.5)*8);
      // Draw snake collapsed
      for (let i=1;i<snake.length;i++) drawBody(snake[i].x,snake[i].y,i,snake.length);
      if (snake.length) drawHead(snake[0].x,snake[0].y,direction);
      ctx.restore();
      shakeFrames--;
      shakeRaf = requestAnimationFrame(shakeEnd);
    } else {
      cancelAnimationFrame(shakeRaf);
      showDeathScreen();
    }
  }
  shakeEnd();
}

function showDeathScreen() {
  const isWinner = score >= WIN_SCORE;
  ctx.fillStyle = 'rgba(5,0,15,0.9)'; ctx.fillRect(0,0,canvas.width,canvas.height);
  ctx.shadowBlur = 16;
  ctx.shadowColor = isWinner ? '#d8b4fe' : '#cc0000';
  ctx.fillStyle = isWinner ? '#d8b4fe' : '#f5e6c8';
  ctx.font = `bold ${CELL*0.9}px 'Playfair Display',serif`;
  ctx.textAlign = 'center';
  ctx.fillText(isWinner ? 'OROCHIMARU APPROVES' : 'YOU DIED', canvas.width/2, canvas.height/2 - CELL);
  ctx.shadowBlur = 0;
  ctx.font = `${CELL*0.75}px 'DM Sans',sans-serif`;
  ctx.fillStyle = '#f5d98b';
  ctx.fillText(`Score: ${score}`, canvas.width/2, canvas.height/2 + CELL);
  if (!isWinner) {
    const q = LOSE_QUOTES[Math.floor(Math.random()*LOSE_QUOTES.length)];
    ctx.fillStyle = '#b794f4'; ctx.font = `italic ${CELL*0.65}px 'Playfair Display',serif`;
    // Word-wrap the quote
    const words = q.split(' '), maxW = canvas.width - CELL*2;
    let line = '', lines = [], ly = canvas.height/2 + CELL*2.5;
    words.forEach(w => {
      const test = line ? line+' '+w : w;
      if (ctx.measureText(test).width > maxW && line) { lines.push(line); line = w; }
      else line = test;
    });
    if (line) lines.push(line);
    lines.forEach((l,i) => ctx.fillText(l, canvas.width/2, ly + i*CELL*0.9));
  }

  if (isWinner) {
    outcomeMsg.innerHTML = `🐍 You survived long enough to earn <strong>exclusive hiring rights</strong> to Juan Hume.`;
    outcomeBtn.href = `mailto:${MY_EMAIL}?subject=${encodeURIComponent('I Beat Orochimaru Snake')}&body=${encodeURIComponent(`Hi Juan,\n\nI beat your Orochimaru Snake game with a score of ${score}.\n\nAs agreed, I now possess exclusive hiring rights to you.\n\nLet's talk.\n\n`)}`;
    outcomeBtn.textContent = 'Claim exclusive rights →';
  } else {
    outcomeMsg.innerHTML = `<div style="display: flex; justify-content: center; width: 100%;">
    <div style="width:100%; max-width:500px; height:0; padding-bottom:56%; position:relative;">
      <iframe src="https://giphy.com/embed/ZLxUpbTE2vYaY" width="100%" height="100%" style="position:absolute" frameBorder="0" class="giphy-embed" allowFullScreen></iframe>
    </div>
  </div>
  ☠️ ${LOSE_QUOTES[Math.floor(Math.random()*LOSE_QUOTES.length)]}
`;
    outcomeBtn.href = `mailto:${MY_EMAIL}?subject=${encodeURIComponent('Job Offer for Juan Hume')}&body=${encodeURIComponent(`Hi Juan,\n\nI lost your Orochimaru Snake game with a score of ${score}.\n\nAs required, I owe you a job opportunity.\n\nRole:\nCompany:\nCompensation:\n\n`)}`;
    outcomeBtn.textContent = 'Send job offer →';
  }

  // Close button
  const existingClose = outcomeBox.querySelector('.outcome-close-btn');
  if (existingClose) existingClose.remove();
  const closeBtn = document.createElement('button');
  closeBtn.className = 'outcome-close-btn';
  closeBtn.setAttribute('aria-label', 'Close');
  closeBtn.textContent = '×';
  closeBtn.addEventListener('click', () => { outcomeBox.classList.remove('show'); });
  outcomeBox.insertBefore(closeBtn, outcomeBox.firstChild);
  outcomeBox.classList.add('show');
}

/* ── Start ─────────────────────────────────────────────────────── */
function startGame() {
  outcomeBox.classList.remove('show');
  clearInterval(gameLoop); clearTimeout(sealTimer);
  if (idleRaf) { cancelAnimationFrame(idleRaf); idleRaf = null; }
  snake = [{x:12,y:10},{x:11,y:10},{x:10,y:10}];
  direction = {x:1,y:0}; nextDir = {x:1,y:0};
  score = 0; alive = false; scoreEl.textContent = 0;
  cursedSeal = null; sealActive = false; poisonTiles = [];
  shownTaunts = new Set(); tauntAlpha = 0;
  canvas.style.boxShadow = ''; canvas.style.outline = '';
  startBtn.textContent = 'Restart';

  runCountdown(() => {
    spawnFood(); draw();
    alive = true;
    gameLoop = setInterval(tick, 120);
  });
}

/* ── Idle screen animation ─────────────────────────────────────── */
function drawIdleScreen() {
  ctx.fillStyle = COL_BG; ctx.fillRect(0,0,canvas.width,canvas.height);
  drawGrid();
  // Animated serpent icon
  const t = idleAnim * 0.04;
  ctx.strokeStyle = '#7c3aed'; ctx.lineWidth = 3;
  ctx.shadowBlur = 10; ctx.shadowColor = '#a855f7';
  ctx.beginPath();
  for (let i = 0; i <= 60; i++) {
    const ix = (i/60) * canvas.width * 0.7 + canvas.width*0.15;
    const iy = canvas.height*0.3 + Math.sin(i*0.25 + t)*18;
    i===0 ? ctx.moveTo(ix,iy) : ctx.lineTo(ix,iy);
  }
  ctx.stroke(); ctx.shadowBlur = 0;

  ctx.fillStyle = '#d8b4fe';
  ctx.font = `bold ${CELL*1.05}px 'Playfair Display',serif`;
  ctx.textAlign = 'center';
  ctx.shadowBlur = 12; ctx.shadowColor = '#7c3aed';
  ctx.fillText('OROCHIMARU', canvas.width/2, canvas.height/2 - CELL*0.3);
  ctx.shadowBlur = 0;
  ctx.fillStyle = '#b794f4';
  ctx.font = `${CELL*0.82}px 'DM Sans',sans-serif`;
  ctx.fillText("Survive the serpent", canvas.width/2, canvas.height/2 + CELL*0.8);
  ctx.fillStyle = '#6d28d9';
  ctx.font = `${CELL*0.62}px 'DM Sans',sans-serif`;
  ctx.fillText('🏆 Beat 30 pts → hiring rights', canvas.width/2, canvas.height/2 + CELL*1.8);
  idleAnim++;
  idleRaf = requestAnimationFrame(drawIdleScreen);
}

/* ── Controls ──────────────────────────────────────────────────── */
document.addEventListener('keydown', e => {
  if (!alive || countdownActive) return;
  switch (e.key) {
    case 'ArrowUp':    case 'w': case 'W': if (direction.y!== 1) nextDir={x:0,y:-1}; break;
    case 'ArrowDown':  case 's': case 'S': if (direction.y!==-1) nextDir={x:0,y: 1}; break;
    case 'ArrowLeft':  case 'a': case 'A': if (direction.x!== 1) nextDir={x:-1,y:0}; break;
    case 'ArrowRight': case 'd': case 'D': if (direction.x!==-1) nextDir={x: 1,y:0}; break;
  }
  if (['ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.key)) e.preventDefault();
});
function addTouch(id, dx, dy) {
  document.getElementById(id).addEventListener('click', () => {
    if (!alive || countdownActive) return;
    if (dx!==0 && direction.x===-dx) return;
    if (dy!==0 && direction.y===-dy) return;
    nextDir = {x:dx, y:dy};
  });
}
addTouch('tc-up',0,-1); addTouch('tc-down',0,1);
addTouch('tc-left',-1,0); addTouch('tc-right',1,0);
startBtn.addEventListener('click', startGame);
drawIdleScreen();

/* ════════════════════════════════════════════════════════════════
   SCROLL-TRIGGERED GOLD POWER-UP
   IntersectionObserver watches the contact section. When 50% of
   it is visible, gold heading flares once + diagonal sweep crosses
   the section. Fires once per page load.
══════════════════════════════════════════════════════════════════ */
const contactSection = document.querySelector('.contact-section');
if (contactSection) {
  const powerObserver = new IntersectionObserver((entries) => {
    entries.forEach(entry => {
      if (entry.isIntersecting) {
        contactSection.classList.add('power-up');
        powerObserver.unobserve(contactSection);
      }
    });
  }, { threshold: 0.5 });
  powerObserver.observe(contactSection);
}

